macro.command:
// Chainbreaker Bolt
// Fired as ammunition (postActiveEffects of the crossbow's attack): on a hit, the bolt arcs to up to five more creatures
// you choose, each within 30 feet of the last one hit and none hit twice. They all take the crossbow's damage dice (rolled
// again, not a critical) plus 3d10 force, from the bolt's Arc activity.
const ARC = "ChainbreakArc000", ARCS = 5, RANGE = 30;
if (args[0]?.tag !== "OnUse" || args[0].macroPass !== "postActiveEffects") return;
if (workflow?.ammunition?.id !== macroItem?.id) return;
const name = macroItem?.name ?? "Chainbreaker Bolt";
let last = workflow.hitTargets?.first();
if (!last) return;
const bolt = workflow.ammunition;
const struck = new Set([last.document.uuid, workflow.token?.document?.uuid]);
const chosen = [];
for (let arc = 1; arc <= ARCS; arc++) {
  const from = last;
  const candidates = MidiQOL.findNearby(null, from, RANGE, { includeIncapacitated: true }).filter(t => !struck.has(t.document.uuid));
  if (!candidates.length) break;
  const pick = await foundry.applications.api.DialogV2.wait({
    window: { title: `${name}: arc ${arc} of ${ARCS}` },
    content: `<p>The bolt arcs from <strong>${from.name}</strong>. Choose the next creature.</p>`,
    buttons: [...candidates.map(t => ({ action: t.document.uuid, label: `${t.name} (${Math.round(MidiQOL.getDistance(from, t))} ft)` })),
      { action: "stop", label: "Stop" }],
    rejectClose: false
  });
  if (!pick || pick === "stop") break;
  last = candidates.find(t => t.document.uuid === pick);
  struck.add(pick);
  chosen.push(last);
}
if (!chosen.length) return;
// the crossbow's damage dice and ability modifier, then 3d10 force
const base = workflow.item.system.damage?.base;
const dice = base?.formula ? `${base.formula} + @mod` : "@mod";
const formula = Roll.replaceFormulaData(dice, workflow.activity?.getRollData?.() ?? workflow.item.getRollData(), { missing: "0" });
const type = base?.types?.first?.() ?? [...(base?.types ?? [])][0] ?? "piercing";
await bolt.update({ [`system.activities.${ARC}.damage.parts`]: [
  { custom: { enabled: true, formula }, types: [type] },
  { number: 3, denomination: 10, types: ["force"], custom: { enabled: false, formula: "" } }] });
const arcActivity = (await fromUuid(bolt.uuid))?.system.activities.get(ARC);
await ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor }), content: `<strong>${name}</strong>: the bolt arcs through ${chosen.map(t => t.name).join(", ")}.` });
await MidiQOL.completeActivityUse(arcActivity, { midiOptions: { targetUuids: chosen.map(t => t.document.uuid),
  workflowOptions: { targetConfirmation: "none", autoRollDamage: "always", autoFastDamage: true } } }, { configure: false }, {});
